    Bug 1943941 - Add debug output to better investigate intermittent fails. r=aleca

    The extra load event may be due to a load in a tab opened by a previous
    test. Seeing the tabId might help to understand what is going on.

    Differential Revision: https://phabricator.services.mozilla.com/D264420

diff --git a/mail/components/extensions/test/browser/browser_ext_clickHandler.js b/mail/components/extensions/test/browser/browser_ext_clickHandler.js
index ff0ffc78310..0cc1939c832 100644
--- a/mail/components/extensions/test/browser/browser_ext_clickHandler.js
+++ b/mail/components/extensions/test/browser/browser_ext_clickHandler.js
@@ -59,7 +59,7 @@ const getCommonFiles = async () => {
               }
               if (log.id && log.id != tabId) {
                 browser.test.fail(
-                  "Should not receive update events for multiple tabs"
+                  `Should not receive update events for multiple tabs (${log.id} & ${tabId})`
                 );
               }
               log.id = tabId;
